R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_harev2/prompts $R/sb_harev2/out
echo  | base64 -d > $R/sb_harev2/prompts/sb_harev2.md
echo sb_harev2 >> $R/sb_queue/queue.txt
mkdir -p $R/sb_ktow2/prompts $R/sb_ktow2/out
echo  | base64 -d > $R/sb_ktow2/prompts/sb_ktow2.md
echo sb_ktow2 >> $R/sb_queue/queue.txt
mkdir -p $R/sb_kobj2/prompts $R/sb_kobj2/out
echo  | base64 -d > $R/sb_kobj2/prompts/sb_kobj2.md
echo sb_kobj2 >> $R/sb_queue/queue.txt
sleep 30; cat $R/sb_queue/queue.txt | tr "\n" " "; echo; tail -3 $R/sb_queue/codexq.log
for s in sb_drev6 sb_brev4 sb_pfrev sb_rkrev sb_f64; do echo "$s log=$(wc -c < $R/$s/cursor.log) verdict=$(ls $R/$s/REVIEW_VERDICT.md 2>/dev/null)"; done
for t in sb_kbox2 sb_rlfix; do d=$(ls -d $R/codex_local/agent/scratch/codex_runs/*_$t 2>/dev/null | tail -1); echo "== $t"; [ -f $d/final_message.md ] && head -c 900 $d/final_message.md; echo; done
